import { listarProdutos } from './produtos.js'
import { criarPedidos } from './pedidos.js'
import { criarFrete } from './frete/index.js'
import { ErroApi, corpoDeErro } from './erros.js'

// Rotas da API. handle() recebe método, caminho e corpo já lido, e devolve { status, body }:
// o server.js só traduz isso para HTTP, e os testes chamam handle() direto.
export function criarApp({ frete = criarFrete(), agora } = {}) {
  const pedidos = criarPedidos({ frete, agora })

  const rotas = [
    ['GET', /^\/produtos$/, () => ({ status: 200, body: { produtos: listarProdutos() } })],
    ['GET', /^\/pedidos$/, (_m, _b, q) => ({ status: 200, body: { pedidos: pedidos.listar({ status: q.get('status') ?? undefined }) } })],
    ['POST', /^\/pedidos$/, async (_m, b) => ({ status: 201, body: await pedidos.criar(b) })],
    ['GET', /^\/pedidos\/([\w-]+)$/, (m) => ({ status: 200, body: pedidos.obter(m[1]) })],
    ['POST', /^\/pedidos\/([\w-]+)\/cancelamento$/, (m, b) => ({ status: 200, body: pedidos.cancelar(m[1], b?.motivo) })]
  ]

  return {
    async handle(method, url, body) {
      const { pathname, searchParams } = new URL(url, 'http://loja.local')
      for (const [verbo, padrao, fn] of rotas) {
        const m = pathname.match(padrao)
        if (m && verbo === method) {
          try {
            return await fn(m, body, searchParams)
          } catch (e) {
            if (e instanceof ErroApi) return { status: e.status, body: corpoDeErro(e) }
            throw e
          }
        }
      }
      return { status: 404, body: corpoDeErro(new ErroApi(404, 'ROTA_INEXISTENTE', `${method} ${pathname} não existe`)) }
    }
  }
}
export class ErroApi extends Error {
  constructor(status, codigo, mensagem) {
    super(mensagem)
    this.status = status
    this.codigo = codigo
  }
}

export function corpoDeErro(e) {
  return { erro: { codigo: e.codigo, mensagem: e.message } }
}
import { obterProduto } from './produtos.js'
import { ErroApi } from './erros.js'

const CEP = /^\d{5}-?\d{3}$/

export function criarPedidos({ frete, agora = () => new Date() }) {
  const pedidos = new Map()
  let seq = 1000

  return {
    async criar(entrada) {
      if (!entrada || !Array.isArray(entrada.itens) || entrada.itens.length === 0) {
        throw new ErroApi(400, 'ITENS_OBRIGATORIOS', 'Informe ao menos um item')
      }
      if (typeof entrada.cep !== 'string' || !CEP.test(entrada.cep)) {
        throw new ErroApi(400, 'CEP_INVALIDO', 'CEP deve ter 8 dígitos')
      }
      let subtotal = 0
      let peso = 0
      const itens = entrada.itens.map((i) => {
        const produto = obterProduto(i.produtoId)
        if (!produto) throw new ErroApi(422, 'PRODUTO_INEXISTENTE', `Produto ${i.produtoId} não existe`)
        const quantidade = Number.isInteger(i.quantidade) && i.quantidade > 0 ? i.quantidade : 1
        subtotal += produto.precoCentavos * quantidade
        peso += produto.pesoGramas * quantidade
        return { produtoId: produto.id, quantidade, precoCentavos: produto.precoCentavos }
      })
      const cepDestino = entrada.cep.replace('-', '')
      let cotacao
      try {
        cotacao = await frete.cotar({ cepDestino, pesoGramas: peso })
      } catch (e) {
        throw new ErroApi(503, 'FRETE_INDISPONIVEL', e.message)
      }
      const id = `ped-${++seq}`
      const pedido = {
        id,
        status: 'aguardando_pagamento',
        itens,
        cep: cepDestino,
        subtotalCentavos: subtotal,
        freteCentavos: cotacao.valorCentavos,
        totalCentavos: subtotal + cotacao.valorCentavos,
        transportadora: cotacao.transportadora,
        criadoEm: agora().toISOString()
      }
      pedidos.set(id, pedido)
      return pedido
    },

    listar({ status } = {}) {
      return [...pedidos.values()].filter((p) => !status || p.status === status)
    },

    obter(id) {
      const p = pedidos.get(id)
      if (!p) throw new ErroApi(404, 'PEDIDO_NAO_ENCONTRADO', `Pedido ${id} não existe`)
      return p
    },

    cancelar(id, motivo) {
      const p = this.obter(id)
      if (p.status === 'enviado') throw new ErroApi(409, 'PEDIDO_JA_ENVIADO', 'Pedido já enviado não pode ser cancelado')
      p.status = 'cancelado'
      p.motivoCancelamento = motivo ?? null
      return p
    }
  }
}
// Cliente da EntregaJá, usada quando a TransNorte não responde. Documentação em openapi/entregaja.yaml.
const BASE = process.env.ENTREGAJA_URL ?? 'https://frete.entregaja.example'

export function criarEntregaJa({ fetch = globalThis.fetch, token = process.env.ENTREGAJA_TOKEN } = {}) {
  return {
    nome: 'entregaja',
    async cotar({ cepDestino, pesoGramas }) {
      const url = `${BASE}/v1/frete?cep=${encodeURIComponent(cepDestino)}&peso=${pesoGramas}`
      const res = await fetch(url, { headers: { authorization: `Bearer ${token ?? ''}` } })
      if (!res.ok) throw new Error(`EntregaJá respondeu ${res.status}`)
      const data = await res.json()
      return { valorCentavos: data.precoCentavos, prazoDias: data.prazo, transportadora: 'entregaja' }
    }
  }
}
import { criarTransNorte } from './transnorte.js'
import { criarEntregaJa } from './entregaja.js'

// Cota com a TransNorte e, se ela falhar, com a EntregaJá.
export function criarFrete({ provedores } = {}) {
  const lista = provedores ?? [criarTransNorte(), criarEntregaJa()]
  return {
    async cotar(pedido) {
      const falhas = []
      for (const p of lista) {
        try {
          return await p.cotar(pedido)
        } catch (e) {
          falhas.push(`${p.nome}: ${e.message}`)
        }
      }
      throw new Error(`Nenhuma transportadora cotou o frete (${falhas.join('; ')})`)
    }
  }
}
// Cliente da TransNorte (cotação de frete). Documentação da API em openapi/transnorte.yaml.
const BASE = process.env.TRANSNORTE_URL ?? 'https://api.transnorte.example/v2'

export function criarTransNorte({ fetch = globalThis.fetch, apiKey = process.env.TRANSNORTE_API_KEY } = {}) {
  return {
    nome: 'transnorte',
    async cotar({ cepDestino, pesoGramas }) {
      const res = await fetch(`${BASE}/cotacoes`, {
        method: 'POST',
        headers: { 'content-type': 'application/json', 'x-api-key': apiKey ?? '' },
        body: JSON.stringify({ cepDestino, pesoKg: pesoGramas / 1000 })
      })
      if (!res.ok) throw new Error(`TransNorte respondeu ${res.status}`)
      const data = await res.json()
      return { valorCentavos: Math.round(data.valor * 100), prazoDias: data.prazoDiasUteis, transportadora: 'transnorte' }
    }
  }
}
// Frete falso para os testes: cota sempre o mesmo valor, sem rede.
export function freteFixo({ valorCentavos = 2500, prazoDias = 4, transportadora = 'transnorte' } = {}) {
  const chamadas = []
  return {
    chamadas,
    async cotar(pedido) {
      chamadas.push(pedido)
      return { valorCentavos, prazoDias, transportadora }
    }
  }
}

export function fetchFalso(resposta, { status = 200 } = {}) {
  const chamadas = []
  const fn = async (url, init = {}) => {
    chamadas.push({ url, init })
    return { ok: status < 400, status, json: async () => resposta }
  }
  fn.chamadas = chamadas
  return fn
}

export const agoraFixo = () => new Date('2026-03-01T12:00:00Z')
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { criarFrete } from '../src/frete/index.js'
import { criarTransNorte } from '../src/frete/transnorte.js'
import { criarEntregaJa } from '../src/frete/entregaja.js'
import { fetchFalso } from './apoio.js'

test('TransNorte cota em reais e converte para centavos', async () => {
  const fetch = fetchFalso({ valor: 23.5, prazoDiasUteis: 3 })
  const r = await criarTransNorte({ fetch, apiKey: 'k' }).cotar({ cepDestino: '01310100', pesoGramas: 1500 })
  assert.deepEqual(r, { valorCentavos: 2350, prazoDias: 3, transportadora: 'transnorte' })
  assert.match(fetch.chamadas[0].url, /\/cotacoes$/)
  assert.equal(JSON.parse(fetch.chamadas[0].init.body).pesoKg, 1.5)
  assert.equal(fetch.chamadas[0].init.headers['x-api-key'], 'k')
})

test('EntregaJá cota por query string', async () => {
  const fetch = fetchFalso({ precoCentavos: 1800, prazo: 5 })
  const r = await criarEntregaJa({ fetch, token: 't' }).cotar({ cepDestino: '01310100', pesoGramas: 700 })
  assert.deepEqual(r, { valorCentavos: 1800, prazoDias: 5, transportadora: 'entregaja' })
  assert.match(fetch.chamadas[0].url, /\/v1\/frete\?cep=01310100&peso=700$/)
})

test('frete usa a EntregaJá quando a TransNorte falha', async () => {
  const falha = { nome: 'transnorte', cotar: async () => { throw new Error('timeout') } }
  const ok = { nome: 'entregaja', cotar: async () => ({ valorCentavos: 1000, prazoDias: 6, transportadora: 'entregaja' }) }
  const r = await criarFrete({ provedores: [falha, ok] }).cotar({ cepDestino: '01310100', pesoGramas: 100 })
  assert.equal(r.transportadora, 'entregaja')
})

test('frete falha com a lista de erros quando todas falham', async () => {
  const falha = (nome) => ({ nome, cotar: async () => { throw new Error('fora') } })
  await assert.rejects(criarFrete({ provedores: [falha('a'), falha('b')] }).cotar({}), /a: fora; b: fora/)
})
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { criarApp } from '../src/app.js'
import { freteFixo, agoraFixo } from './apoio.js'

const novoApp = (frete = freteFixo()) => criarApp({ frete, agora: agoraFixo })

test('POST /pedidos cria o pedido com frete e total', async () => {
  const frete = freteFixo({ valorCentavos: 1990 })
  const app = novoApp(frete)
  const r = await app.handle('POST', '/pedidos', { itens: [{ produtoId: 'p-100', quantidade: 2 }], cep: '01310-100' })
  assert.equal(r.status, 201)
  assert.equal(r.body.subtotalCentavos, 9980)
  assert.equal(r.body.freteCentavos, 1990)
  assert.equal(r.body.totalCentavos, 11970)
  assert.equal(r.body.cep, '01310100')
  assert.equal(r.body.status, 'aguardando_pagamento')
  assert.deepEqual(frete.chamadas[0], { cepDestino: '01310100', pesoGramas: 700 })
})

test('POST /pedidos recusa CEP inválido', async () => {
  const r = await novoApp().handle('POST', '/pedidos', { itens: [{ produtoId: 'p-100' }], cep: '123' })
  assert.equal(r.status, 400)
  assert.equal(r.body.erro.codigo, 'CEP_INVALIDO')
})

test('POST /pedidos recusa pedido sem itens', async () => {
  const r = await novoApp().handle('POST', '/pedidos', { itens: [], cep: '01310100' })
  assert.equal(r.status, 400)
  assert.equal(r.body.erro.codigo, 'ITENS_OBRIGATORIOS')
})

test('POST /pedidos recusa produto inexistente', async () => {
  const r = await novoApp().handle('POST', '/pedidos', { itens: [{ produtoId: 'p-999' }], cep: '01310100' })
  assert.equal(r.status, 422)
})

test('GET /pedidos filtra por status', async () => {
  const app = novoApp()
  const a = await app.handle('POST', '/pedidos', { itens: [{ produtoId: 'p-100' }], cep: '01310100' })
  await app.handle('POST', '/pedidos', { itens: [{ produtoId: 'p-200' }], cep: '01310100' })
  await app.handle('POST', `/pedidos/${a.body.id}/cancelamento`, { motivo: 'desistiu' })
  const r = await app.handle('GET', '/pedidos?status=cancelado')
  assert.equal(r.body.pedidos.length, 1)
  assert.equal(r.body.pedidos[0].motivoCancelamento, 'desistiu')
})

test('GET /pedidos/{id} devolve 404 para pedido que não existe', async () => {
  const r = await novoApp().handle('GET', '/pedidos/ped-1')
  assert.equal(r.status, 404)
  assert.equal(r.body.erro.codigo, 'PEDIDO_NAO_ENCONTRADO')
})

test('POST /pedidos devolve 503 quando nenhuma transportadora cota', async () => {
  const frete = { cotar: async () => { throw new Error('fora do ar') } }
  const r = await novoApp(frete).handle('POST', '/pedidos', { itens: [{ produtoId: 'p-100' }], cep: '01310100' })
  assert.equal(r.status, 503)
  assert.equal(r.body.erro.codigo, 'FRETE_INDISPONIVEL')
})
# Arquitetura

A Loja API recebe os pedidos do site e do app, guarda os pedidos e cota o frete com as
transportadoras parceiras. A TransNorte é a transportadora principal; a EntregaJá é a reserva,
chamada só quando a TransNorte não responde.

```mermaid
C4Context
  title Contexto da Loja API
  Person(cliente, "Cliente", "Compra pelo site ou pelo app")
  System(loja, "Loja API", "Pedidos e frete")
  System_Ext(transnorte, "TransNorte", "Cotação de frete e rastreio")
  System_Ext(entregaja, "EntregaJá", "Cotação de frete (reserva)")
  Rel(cliente, loja, "Faz pedidos", "HTTPS")
  Rel(loja, transnorte, "Cota o frete", "HTTPS")
  Rel(loja, entregaja, "Cota o frete se a TransNorte falhar", "HTTPS")
```

## Componentes

| Componente | Arquivo | Papel |
| --- | --- | --- |
| Rotas | `src/app.js` | Traduz método e caminho para as operações de pedidos |
| Pedidos | `src/pedidos.js` | Valida, soma os itens, cota o frete e guarda o pedido |
| Frete | `src/frete/index.js` | Tenta as transportadoras em ordem: TransNorte, depois EntregaJá |
| Cliente TransNorte | `src/frete/transnorte.js` | `POST /cotacoes`, com `X-Api-Key` |
| Cliente EntregaJá | `src/frete/entregaja.js` | `GET /v1/frete`, com token Bearer |
| Catálogo | `src/produtos.js` | Produtos, preços e pesos |
# Frete

O frete é cotado na criação do pedido, pelo peso somado dos itens e pelo CEP de entrega.

1. A Loja pede a cotação à **TransNorte** (`POST /cotacoes`, peso em kg). O valor vem em reais e
   é convertido para centavos.
2. Se a TransNorte falhar (erro HTTP ou rede), a Loja pede à **EntregaJá** (`GET /v1/frete`, peso
   em gramas). O valor já vem em centavos.
3. Se as duas falharem, o pedido não é criado e a API devolve `503 FRETE_INDISPONIVEL`, com a
   falha de cada transportadora na mensagem.

O campo `transportadora` do pedido diz quem cotou: `transnorte` ou `entregaja`.

## Configuração

| Variável | Uso |
| --- | --- |
| `TRANSNORTE_URL` | Base da API da TransNorte (padrão `https://api.transnorte.example/v2`) |
| `TRANSNORTE_API_KEY` | Chave da TransNorte, enviada em `X-Api-Key` |
| `ENTREGAJA_URL` | Base da API da EntregaJá (padrão `https://frete.entregaja.example`) |
| `ENTREGAJA_TOKEN` | Token da EntregaJá, enviado como `Authorization: Bearer` |
# Guia de integração

Este guia mostra como um canal de venda cria e acompanha um pedido.

## Criar um pedido

Mande os itens e o `cep` de entrega (com ou sem hífen). A API soma os itens, cota o frete e
devolve o pedido com o total.

```http
POST /pedidos
Content-Type: application/json

{
  "itens": [{ "produtoId": "p-100", "quantidade": 2 }],
  "cep": "01310-100"
}
```

```json
{
  "id": "ped-1001",
  "status": "aguardando_pagamento",
  "itens": [{ "produtoId": "p-100", "quantidade": 2, "precoCentavos": 4990 }],
  "cep": "01310100",
  "subtotalCentavos": 9980,
  "freteCentavos": 1990,
  "totalCentavos": 11970,
  "transportadora": "transnorte",
  "criadoEm": "2026-03-01T12:00:00.000Z"
}
```

Erros: `400 ITENS_OBRIGATORIOS` ou `400 CEP_INVALIDO`, `422 PRODUTO_INEXISTENTE` e
`503 FRETE_INDISPONIVEL` quando nenhuma transportadora cota.

## Acompanhar e cancelar

`GET /pedidos/{id}` devolve o pedido. `GET /pedidos?status=cancelado` filtra a lista.
`POST /pedidos/{id}/cancelamento` cancela um pedido que ainda não foi enviado (`409
PEDIDO_JA_ENVIADO` se já foi), com um `motivo` opcional.

## Endpoints

| Método | Caminho | O que faz |
| --- | --- | --- |
| GET | `/produtos` | Lista os produtos |
| GET | `/pedidos` | Lista os pedidos, com filtro `status` |
| POST | `/pedidos` | Cria um pedido e cota o frete |
| GET | `/pedidos/{id}` | Um pedido |
| POST | `/pedidos/{id}/cancelamento` | Cancela um pedido |
# Loja API

API de pedidos da Loja: produtos, pedidos, cancelamento e cotação de frete com as transportadoras
parceiras (TransNorte e, como reserva, EntregaJá).

```bash
npm start   # http://localhost:3000
npm test
```

- Especificação da API: [`openapi/loja.yaml`](openapi/loja.yaml); APIs das transportadoras em
  [`openapi/transnorte.yaml`](openapi/transnorte.yaml) e [`openapi/entregaja.yaml`](openapi/entregaja.yaml).
- Documentação: [arquitetura](docs/arquitetura.md), [frete](docs/frete.md) e
  [guia de integração](docs/guia-de-integracao.md).
openapi: 3.1.0
info:
  title: Loja API
  version: 1.3.0
  description: API de pedidos da Loja. Calcula o frete com as transportadoras parceiras.
servers:
  - url: https://api.loja.example
    description: Produção
  - url: http://localhost:3000
    description: Local
security:
  - apiKey: []
paths:
  /produtos:
    get:
      operationId: listarProdutos
      summary: Lista os produtos à venda
      responses:
        '200':
          description: Produtos
          content:
            application/json:
              schema:
                type: object
                required: [produtos]
                properties:
                  produtos:
                    type: array
                    items:
                      $ref: '#/components/schemas/Produto'
  /pedidos:
    get:
      operationId: listarPedidos
      summary: Lista os pedidos
      parameters:
        - name: status
          in: query
          required: false
          description: Filtra pelo status do pedido
          schema:
            $ref: '#/components/schemas/StatusPedido'
      responses:
        '200':
          description: Pedidos
          content:
            application/json:
              schema:
                type: object
                required: [pedidos]
                properties:
                  pedidos:
                    type: array
                    items:
                      $ref: '#/components/schemas/Pedido'
    post:
      operationId: criarPedido
      summary: Cria um pedido e cota o frete
      description: >-
        Soma os itens, cota o frete com a TransNorte e, se ela não responder, com a EntregaJá.
        Sem nenhuma cotação, devolve 503.
      requestBody:
        required: true
        content:
          application/json:
            schema:
              $ref: '#/components/schemas/NovoPedido'
            example:
              itens:
                - produtoId: p-100
                  quantidade: 2
              cep: 01310-100
      responses:
        '201':
          description: Pedido criado
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/Pedido'
              example:
                id: ped-1001
                status: aguardando_pagamento
                itens:
                  - produtoId: p-100
                    quantidade: 2
                    precoCentavos: 4990
                cep: '01310100'
                subtotalCentavos: 9980
                freteCentavos: 1990
                totalCentavos: 11970
                transportadora: transnorte
                criadoEm: '2026-03-01T12:00:00.000Z'
        '400':
          $ref: '#/components/responses/Erro'
        '422':
          $ref: '#/components/responses/Erro'
        '503':
          $ref: '#/components/responses/Erro'
  /pedidos/{id}:
    get:
      operationId: obterPedido
      summary: Um pedido
      parameters:
        - $ref: '#/components/parameters/IdPedido'
      responses:
        '200':
          description: Pedido
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/Pedido'
        '404':
          $ref: '#/components/responses/Erro'
  /pedidos/{id}/cancelamento:
    post:
      operationId: cancelarPedido
      summary: Cancela um pedido ainda não enviado
      parameters:
        - $ref: '#/components/parameters/IdPedido'
      requestBody:
        required: false
        content:
          application/json:
            schema:
              type: object
              properties:
                motivo:
                  type: string
      responses:
        '200':
          description: Pedido cancelado
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/Pedido'
        '404':
          $ref: '#/components/responses/Erro'
        '409':
          $ref: '#/components/responses/Erro'
components:
  securitySchemes:
    apiKey:
      type: apiKey
      in: header
      name: X-Api-Key
      description: Chave do canal de venda, em LOJA_API_KEY
  parameters:
    IdPedido:
      name: id
      in: path
      required: true
      schema:
        type: string
        pattern: '^ped-\d+$'
  responses:
    Erro:
      description: Erro com código estável
      content:
        application/json:
          schema:
            $ref: '#/components/schemas/Erro'
  schemas:
    Produto:
      type: object
      required: [id, nome, precoCentavos, pesoGramas]
      properties:
        id: { type: string }
        nome: { type: string }
        precoCentavos: { type: integer }
        pesoGramas: { type: integer }
    StatusPedido:
      type: string
      enum: [aguardando_pagamento, pago, enviado, cancelado]
    NovoPedido:
      type: object
      required: [itens, cep]
      properties:
        itens:
          type: array
          minItems: 1
          items:
            type: object
            required: [produtoId]
            properties:
              produtoId: { type: string }
              quantidade: { type: integer, minimum: 1, default: 1 }
        cep:
          type: string
          pattern: '^\d{5}-?\d{3}$'
          description: CEP de entrega, com ou sem hífen
    Pedido:
      type: object
      required: [id, status, itens, cep, subtotalCentavos, freteCentavos, totalCentavos, transportadora, criadoEm]
      properties:
        id: { type: string }
        status: { $ref: '#/components/schemas/StatusPedido' }
        itens:
          type: array
          items:
            type: object
            properties:
              produtoId: { type: string }
              quantidade: { type: integer }
              precoCentavos: { type: integer }
        cep: { type: string, description: CEP de entrega só com dígitos }
